"use client";

import { useEffect, useRef } from "react";
import TransitionalLink from "@utils/TransitionalLink";
import "@styles/components/layouts/morebar.style.css";
import { useAuth } from "@providers/AuthProvider";
import { useRouter } from "next/navigation";
import { useTheme } from "@providers/ThemeProvider";
import { useAppContext } from "@providers/AppContext";
import UsernameSideCard from "@components/ui/cards/username-side-card";


type Props = {
  onClickToggle: () => void;
  position: {
    zIndex: number;
    width: string;
    height: string;
    top: string;
    left: string;
    right: string;
    bottom: string;
  };
};

export default function MainMenu({ onClickToggle, position }: Props) {
  // const { userInfo, setUser } = useAuth();
  const router = useRouter();
  const { darkTheme, toggleTheme } = useTheme();
  const mainMenuRef = useRef<HTMLDivElement>(null);
  const { toggleSettings } = useAppContext();
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (
        mainMenuRef.current &&
        !mainMenuRef.current.contains(event.target as Node)
      ) {
        onClickToggle();
      }
    };

    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, [onClickToggle]);

  const userInfo = null;

  return (
    <div className="fixed border border-solid border-border rounded-[18px] bg-bg-tertiary w-full h-auto" style={position}>
      <div ref={mainMenuRef} className="h-auto w-auto p-2">
        {userInfo ? (
          <div
            className="flex flex-col items-start justify-center gap-2 text-text
            rounded-[25px] text-[15px] font-montserrat-sans cursor-pointer h-auto"
          >
            <div className="flex items-center justify-center border-b border-solid border-border pb-2 w-full h-auto">
              <UsernameSideCard />
            </div>
            <div className="w-full h-[40px] flex items-center justify-start px-2 py-1 hover:bg-bg-hover transition-all duration-300 ease-in-out rounded-[13px]">
              <a>SignOut</a>
            </div>
            <div className="w-full h-[40px] flex items-center justify-start px-2 py-1 hover:bg-bg-hover transition-all duration-300 ease-in-out rounded-[13px]">
              <p onClick={toggleSettings}>
                Settings
              </p>
            </div>

          </div>
        ) : (
          <div
            className="flex flex-col items-start justify-center gap-2 text-text
            rounded-[25px] text-[15px] font-montserrat-sans cursor-pointer h-auto"
          >
            <div className="flex items-center justify-center border-b border-solid border-border pb-2 w-full h-auto">
              <UsernameSideCard />
            </div>
            <div className="w-full h-[40px] flex items-center justify-start px-2 py-1 hover:bg-bg-hover transition-all duration-300 ease-in-out rounded-[13px]">
              <TransitionalLink href="/auth/signin" onClick={onClickToggle}>
                SignIn
              </TransitionalLink>
            </div>
            <div className="w-full h-[40px] flex items-center justify-start px-2 py-1 hover:bg-bg-hover transition-all duration-300 ease-in-out rounded-[13px]">
              <TransitionalLink href="/auth/signup" onClick={onClickToggle}>
                SignUp
              </TransitionalLink>
            </div>
            <div className="w-full h-[40px] flex items-center justify-start px-2 py-1 hover:bg-bg-hover transition-all duration-300 ease-in-out rounded-[13px]">
              <p onClick={toggleTheme}>
                {darkTheme ? "Switch Light Mode" : "Switch Dark Mode"}
              </p>
            </div>
            <div className="w-full h-[40px] flex items-center justify-start px-2 py-1 hover:bg-bg-hover
            transition-all duration-300 ease-in-out rounded-[13px]" onClick={toggleSettings}>
              <p>
                Settings
              </p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
